# Apply column-dominant fill strategy
grid = [list(map(int, line.split())) for line in grid_data.strip().split('\n')]

# For each column, find the most common non-3 value
from collections import Counter
dominant = {}
for col in range(30):
    vals = [row[col] for row in grid if row[col] != 3]
    cnt = Counter(vals)
    if cnt:
        dominant[col] = cnt.most_common(1)[0][0]
    else:
        dominant[col] = None

print("Column dominants:", dominant)

# Create output by filling 3s with dominant values
output_grid = []
for i in range(29):
    row = list(grid[i])
    for col in range(30):
        if row[col] == 3 and dominant[col] is not None:
            row[col] = dominant[col]
    output_grid.append(row)

print({"action": "submit", "grid": output_grid})

# Analyze what values appear in triggered rows per column
grid = [list(map(int, line.split())) for line in grid_data.strip().split('\n')]

triggered_rows = [i for i, r in enumerate(grid) if r[5] == 0]
print(f"Triggered row indices: {triggered_rows}")

# For each column, find the most common non-3, non-background value in triggered rows
from collections import Counter
triggered_col_stats = {}
for col in range(30):
    vals = [(i, grid[i][col]) for i in triggered_rows if grid[i][col] != 3]
    counts = Counter(v for _, v in vals)
    if counts:
        triggered_col_stats[col] = {'most_common': counts.most_common(3), 'count': len(vals)}
    else:
        triggered_col_stats[col] = {'most_common': [], 'count': 0}

print("\nMost common values in triggered rows:")
for col in sorted(triggered_col_stats.keys()):
    data = triggered_col_stats[col]
    if data['count'] > 0:
        print(f"Col {col}: {[(v,c) for v,c in data['most_common']]}")
